solution:
import { useState } from 'react';

export function useList(initial = []) {
  const [list, setList] = useState(initial);
  return {
    list,
    push: (item) => setList(l => [...l, item]),
    remove: (index) => setList(l => l.filter((_, i) => i !== index)),
    clear: () => setList([]),
  };
}
